    %one_bc = "stablehlo.broadcast_in_dim"(%one) {broadcast_dimensions = dense<[]> : tensor<0xi64>} : (tensor<f32>) -> tensor<5x8xf32>
    %zero_bc = "stablehlo.broadcast_in_dim"(%zero) {broadcast_dimensions = dense<[]> : tensor<0xi64>} : (tensor<f32>) -> tensor<5x8xf32>
    // Select: if mask then 1.0 else 0.0
    %out = "stablehlo.select"(%mask, %one_bc, %zero_bc) : (tensor<5x8xi1>, tensor<5x8xf32>, tensor<5x8xf32>) -> tensor<5x8xf32>
    return %out : tensor<5x8xf32>
  }
}
